using System;
using System.Threading.Tasks;
using ZBank.Application.Common.Interfaces;

namespace ZBank.Application.Auth;

// Usually we would store the nonce in Redis with a short TTL, but for simplicity
// we generate it here and the client signs it. In a real scenario we must validate 
// that the nonce was generated by us recently.
public class BiometricChallengeResponse
{
    public string Nonce { get; set; } = string.Empty;
}

public class BiometricChallengeUseCase
{
    private readonly ICryptoService _cryptoService;

    public BiometricChallengeUseCase(ICryptoService cryptoService)
    {
        _cryptoService = cryptoService;
    }

    public Task<BiometricChallengeResponse> ExecuteAsync()
    {
        var nonce = _cryptoService.GenerateNonce();
        return Task.FromResult(new BiometricChallengeResponse { Nonce = nonce });
    }
}
